import json
# Reduce volumes in batch_compose2.json to avoid clipping.
with open('batch_compose2.json') as f:
    batch=json.load(f)
for call in batch:
    if call['name']=='pattern_set_cell':
        a=call['arguments']
        ch=a['channel']
        vol=a.get('volume',64)
        # scale
        if ch in [0,1,2]:
            new=int(vol*0.75)
        elif ch==3:
            new=int(vol*0.85)
        elif ch in [4,5]:
            new=vol
        elif ch==6:
            new=int(vol*0.8)
        elif ch==7:
            new=int(vol*0.7)
        else:
            new=vol
        a['volume']=max(1,new)
with open('batch_compose2.json','w') as f:
    json.dump(batch,f)
print('volumes scaled')
